import{_ as o,o as t,c as d,a0 as c}from"./chunks/framework.DQOulFGV.js";const p=JSON.parse('{"title":"Momus-MCP — Real-World Validation Findings","description":"","frontmatter":{},"headers":[],"relativePath":"11-real-world-findings.md","filePath":"11-real-world-findings.md"}'),s={name:"11-real-world-findings.md"};function r(n,e,a,i,l,m){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="momus-mcp-—-real-world-validation-findings" tabindex="-1">Momus-MCP — Real-World Validation Findings <a class="header-anchor" href="#momus-mcp-—-real-world-validation-findings" aria-label="Permalink to &quot;Momus-MCP — Real-World Validation Findings&quot;">​</a></h1><blockquote><p><strong>Live report.</strong> Updated as we validate Momus against two real, independent AraneaDev repositories plus Momus itself (dogfooding). This is the honest record of (a) what Momus reports about those codebases and (b) the bugs we found in Momus while doing so. Non-normative (see <code>docs/README</code>).</p></blockquote><p><strong>Last updated:</strong> 2026-08-16</p><h2 id="_1-targets" tabindex="-1">1. Targets <a class="header-anchor" href="#_1-targets" aria-label="Permalink to &quot;1. Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>Language</th><th>Scale</th><th>Test stack</th><th>Momus config used</th></tr></thead><tbody><tr><td><code>/root/Chaos-MCP</code></td><td>TypeScript (ESM, NodeNext)</td><td>320 files, 97 test files</td><td>Vitest (<code>vi.*</code>), Stryker mutation testing</td><td>default TS</td></tr><tr><td><code>/root/Knossos-MCP</code></td><td>PHP ≥ 8.3</td><td>154 src + 221 test files</td><td>PHPUnit 12, Infection</td><td><code>.momusrc</code> → <code>{languages:{php:true}}</code> (temp)</td></tr><tr><td><code>Momus-MCP</code> (self)</td><td>TypeScript + PHP</td><td>59 audited files</td><td>Vitest</td><td><code>.momusrc</code> (fixtures excluded)</td></tr></tbody></table><h2 id="_2-bugs-found-in-momus-and-fixed" tabindex="-1">2. Bugs found in Momus (and fixed) <a class="header-anchor" href="#_2-bugs-found-in-momus-and-fixed" aria-label="Permalink to &quot;2. Bugs found in Momus (and fixed)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Commit</th><th>Bug</th><th>Symptom on real code</th></tr></thead><tbody><tr><td>1</td><td><code>33b9847</code></td><td>CLI space-separated flag values leaked into positional paths</td><td><code>momus audit --max-issues 50</code> treated <code>50</code> as a path</td></tr><tr><td>2</td><td><code>33b9847</code></td><td>DRIFT-005 checked symbol-only exports, not all named exports</td><td>false <code>missing-export</code> for <code>const</code>/<code>type</code>/<code>enum</code> exports (<code>TOOL_DEFINITION</code> etc.)</td></tr><tr><td>3</td><td><code>33b9847</code></td><td><code>extractSymbols</code> ignored barrel re-exports</td><td><code>export { X } from &#39;...&#39;</code> names treated as missing</td></tr><tr><td>4</td><td><code>33b9847</code></td><td>IR cache not invalidated by tool version</td><td>stale cached IR served after a parser change</td></tr><tr><td>5</td><td><code>0504b57</code></td><td>TS contract synthesis always emitted <code>undefined</code></td><td>useless <code>mockReturnValue(undefined)</code></td></tr><tr><td>6</td><td><code>1620215</code></td><td><code>momus drift</code> (and precommit/hook) didn&#39;t recompute summary</td><td>drift-only scan printed full-audit counts + wrong <code>CLEAN</code></td></tr><tr><td>7</td><td><code>1620215</code></td><td>TS synthesis used <code>mockReturnValue(Promise.resolve(...))</code></td><td>wrong async semantics</td></tr><tr><td>8</td><td><code>f08bec6</code></td><td>PHP <code>valueText()</code> fell back to AST node <code>kind</code></td><td><strong>50 false TAUT-001 &quot;self-comparison&quot; errors</strong> on Knossos</td></tr><tr><td>9</td><td><em>(this round)</em></td><td>TS <code>instanceIds</code> was a flat name→id map, so a name reused across test scopes (<code>mockRun</code>) resolved every use to the <strong>last</strong> binding</td><td>82 false TAUT-005 on Chaos-MCP <code>handler.test.ts</code></td></tr><tr><td>10</td><td><em>(this round)</em></td><td>Chained-config initializers (<code>const f = vi.fn().mockReturnValue(1)</code>) and inline <code>vi.fn().mockXxx(...)</code> inside object/array literals were never marked reachable</td><td>more false TAUT-005 (see #9&#39;s fix — folded into the same change)</td></tr><tr><td>11</td><td><em>(this round)</em></td><td><code>momus contract</code> on PHP reimplemented TS-only synthesis, ignoring <code>--framework phpunit</code></td><td>emitted <code>satisfies Partial&lt;...&gt;</code> garbage for a PHP class</td></tr><tr><td>12</td><td><em>(this round)</em></td><td>Default <code>ignorePatterns</code> omitted <code>**/vendor/**</code> (Composer deps)</td><td>Knossos audit scanned 3,808 files incl. 3,915 vendor <code>.php</code> files (70s) instead of 403 files (8.5s)</td></tr><tr><td>13</td><td><em>(this round)</em></td><td><code>productionCalls</code> missed a SUT assigned in <code>beforeEach</code>, local helpers wrapping the SUT, and <code>it.each</code> parameterized tests</td><td>21 false TAUT-004 &quot;mock-only-assertion&quot; on Chaos-MCP</td></tr><tr><td>14</td><td><em>(this round)</em></td><td>PHP mocks handed to production via <code>new Foo($mock)</code>, passed as a call argument, or returned from a <code>willReturnCallback</code> closure were never marked reachable</td><td>5 false TAUT-005 &quot;zero-reach&quot; on Knossos-MCP</td></tr><tr><td>15</td><td><em>(this round)</em></td><td><code>productionCalls</code> did not count dynamic <code>import()</code> as executing production code</td><td>1 false TAUT-004 on Chaos-MCP <code>sandbox.test.ts</code> (signal-handler re-import pattern)</td></tr><tr><td>16</td><td><em>(dogfood)</em></td><td><code>synthesize_mock_contract</code> synthesized <code>{ length: 0 }</code> for string-literal union aliases (<code>Language</code>/<code>MockFramework</code>/<code>SymbolKind</code>) because <code>getPropertiesOfType</code> returns the primitive <code>String</code>&#39;s intrinsic <code>length</code></td><td>garbage mock contracts for Momus&#39;s own <code>ModuleIR</code>/<code>SymbolIR</code></td></tr><tr><td>17</td><td><em>(dogfood)</em></td><td>inline type literals (<code>{ lang: Language }</code>) recursed through the non-checker <code>tsReturnExample</code>, so named union members emitted <code>undefined</code></td><td><code>{ lang: undefined, sev: undefined }</code> for a union-field return</td></tr><tr><td>18</td><td><em>(dogfood)</em></td><td>generic methods (<code>identity&lt;T&gt;(x: T): T</code>) emitted <code>vi.fn&lt;[x: T], T&gt;()</code> — an out-of-scope <code>T</code> (invalid TypeScript)</td><td>broken mock contract for generic methods</td></tr><tr><td>19</td><td><em>(dogfood)</em></td><td>generic classes (<code>Box&lt;T&gt;</code>) emitted <code>vi.fn&lt;[], T&gt;()</code> + <code>Partial&lt;Box&gt;</code> (missing type arg)</td><td>invalid TypeScript for generic classes</td></tr><tr><td>20</td><td><em>(dogfood)</em></td><td><code>synthesize_mock_contract</code> returned <code>no class found</code> for interface targets, despite the documented &quot;class/interface&quot; contract</td><td>interface-only files were unmockable</td></tr><tr><td>21</td><td><em>(coverage pass)</em></td><td><code>tsReturnExample</code>&#39;s union nullish-exclusion missed <code>null</code> parsed as a <code>LiteralType</code> (not <code>NullKeyword</code>)</td><td><code>null | undefined</code> synthesized as <code>&#39;null&#39;</code> instead of <code>&#39;undefined&#39;</code></td></tr><tr><td>22</td><td><em>(coverage pass)</em></td><td><code>gitChangedPaths</code> returned <strong>toplevel</strong>-relative paths when <code>root</code> was a subdirectory of the repo</td><td>diff scoping silently no-oped for subdir roots (paths never matched module paths)</td></tr><tr><td>23</td><td><em>(open items)</em></td><td>PHP <code>willThrowException</code> was recognized for reachability but its exception value never reached the IR</td><td>throw-configured mocks couldn&#39;t be inspected; open improvement §5.1 — now recorded (mock-level config, deliberately not a return value so DRIFT-003 never compares an exception against the production return type)</td></tr><tr><td>24</td><td><em>(open items)</em></td><td><code>synthesize_mock_contract</code> emitted <code>undefined</code> for <code>Record&lt;K, V&gt;</code> / <code>NodeJS.ProcessEnv</code> index-signature types (no named properties in <code>getPropertiesOfType</code>)</td><td><code>{}</code> is the type-correct placeholder; index-signature detection added to both the syntax-only and checker paths</td></tr><tr><td>25</td><td><em>(open items)</em></td><td>synthesized contracts emitted bare <code>(x)</code> for unannotated parameters</td><td><code>paramTypeText</code> now infers <code>number</code>/<code>string</code>/<code>boolean</code>/<code>unknown[]</code>/<code>Record&lt;string, unknown&gt;</code> from the default initializer; <code>unknown</code> only when no signal exists</td></tr><tr><td>26</td><td><em>(coverage pass)</em></td><td>PHPDoc <code>@return array&lt;int, Invoice&gt;</code> (generics containing spaces) was truncated to <code>array&lt;int,</code> — the first-whitespace token split</td><td>wrong TypeIR (<code>named: &#39;array&lt;int,&#39;</code> instead of <code>array</code> of <code>Invoice</code>); <code>docTypeFromRest</code> now consumes tokens until a <code>$</code> or a description word</td></tr><tr><td>27</td><td><em>(dogfood/coverage)</em></td><td>TS DRIFT-003 was dead for <code>vi.spyOn</code> configs: spy-bound configs (<code>const spy = vi.spyOn(x, &#39;m&#39;); spy.mockReturnValue(v)</code>) were attached at mock level only, then <strong>wiped</strong> when the instance-mock pass rebuilt <code>configuredValues</code> from member return values — the assigned value never reached the checker</td><td><code>spy.mockReturnValue(&#39;nope&#39;)</code> on a <code>number</code>-returning method was silent; now the spyOn assignability pass computes DRIFT-003 (fixture: planted <code>&#39;nope&#39;</code> fires, healthy <code>42</code> quiet)</td></tr><tr><td>28</td><td><em>(dogfood/coverage)</em></td><td><code>collectAssignedConfigs</code> resolved config owners through the <strong>flat</strong> <code>instanceIds</code> map, so a name reused across test scopes (<code>spy</code>) attached configs to the last binding</td><td>wrong-mock config attachment; now position-aware (<code>resolveInstance</code> nearest-binding)</td></tr><tr><td>29</td><td><em>(dogfood/coverage)</em></td><td><code>literalShape</code> didn&#39;t unwrap casts, so <code>mockReturnValue(&#39;x&#39; as T)</code> yielded no value</td><td><code>&#39;x&#39; as unknown as number</code> produced <code>value: undefined</code>; casts/parens now unwrap</td></tr><tr><td>30</td><td><em>(dogfood)</em></td><td><code>momus hook --install --root DIR</code> (and every non-<code>serve</code> command) ignored <code>--root</code> — <code>main</code> used <code>process.cwd()</code></td><td>the hook installer wrote <code>.git/hooks/pre-commit</code> into the <strong>wrong repo</strong>; <code>--root</code> is now honored by every command</td></tr><tr><td>31</td><td><em>(dogfood)</em></td><td><code>mockRejectedValue</code>/<code>mockRejectedValueOnce</code> configs were checked against the production return type — but a rejection <strong>reason</strong> is not a resolved value</td><td><code>spy.mockRejectedValue(new Error(&#39;boom&#39;))</code> on a <code>Promise&lt;string&gt;</code> method false-flagged DRIFT-003; rejection configs are now skipped in assignability</td></tr><tr><td>32</td><td><em>(coverage pass)</em></td><td>DRIFT-002&#39;s <code>typeAssignable</code> checked target-union <strong>before</strong> source-union, so a stub param typed <code>string|number</code> could not accept a production <code>string|number</code> param</td><td>identical union types falsely flagged as signature-mismatch; source unions now recurse first (each source member must be accepted by the target)</td></tr><tr><td>33</td><td><em>(refactor)</em></td><td>CLI <code>main()</code> was one giant switch: commands weren&#39;t unit-testable without spawning a subprocess (CLI entrypoint coverage 19.4%)</td><td>extracted exported per-command functions (<code>runAudit</code>/<code>runDrift</code>/<code>runPrecommit</code>/<code>runHook</code>/<code>runContract</code>/<code>runRules</code>/<code>runServe</code>/<code>runInit</code>/<code>runDoctor</code>/<code>runAnnotate</code>/<code>runAnnotatePr</code>) + thin mapper; 2 direct tests, CLI stmts 19.4→37.8%</td></tr><tr><td>34</td><td><em>(coverage pass)</em></td><td>coverage gaps in <code>markdown.ts</code> pluralization, <code>symbolIndex.ts</code> dedupe/inheritance/resolveByName, and the PHP <code>phpReturnAssignable</code> tree were uncovered</td><td>new unit tests took markdown.ts + symbolIndex.ts to 100% stmts/branches and covered every PHP DRIFT-003 branch (mixed/void/null/union/class-resolution)</td></tr><tr><td>35</td><td><em>(coverage pass)</em></td><td><code>SYS-004</code> (perf budget §2.7) was declared in the IR taxonomy but <strong>never emitted</strong> — the spec&#39;s &quot;degrades to info, never crashes&quot; contract was unexercised</td><td>a per-file parse-time budget (<code>parseBudgetMs</code>, default 2s) now emits a SYS-004 info diagnostic; deterministic busy-wait-parser tests cover the fires + quiet paths</td></tr><tr><td>36</td><td><em>(coverage pass)</em></td><td><code>dataflow.ts</code> block-bodied <code>mockImplementation</code> returns (<code>{ return 42; }</code>, <code>function () {}</code>) fell back to raw source text; the <code>extractCommentsForModule</code> wrapper was dead code</td><td>literal extraction now walks block bodies (arrow + function-expression), non-literal blocks keep full text; dead wrapper removed; <code>typeAssignable</code>/<code>phpReturnAssignable</code> named-primitive + void/literal fallthrough branches covered</td></tr><tr><td>37</td><td><em>(process)</em></td><td>lint + format:check were scripts but not wired into CI</td><td><code>ci.yml</code> test job now runs both gates after the test step</td></tr><tr><td>38</td><td><em>(coverage pass)</em></td><td><code>phpValue</code> classified <code>new X()</code> as a <strong>literal</strong> (<code>constant: true</code>), so a fresh-object comparison (<code>assertNotSame(new Engine(), $engine)</code>) could be read as a self-comparison by TAUT-001</td><td><code>new</code> expressions now skip the literal path and classify via <code>exprKind</code> → <code>&#39;new&#39;</code> (re-evaluating, never constant); regression test pins the classification</td></tr><tr><td>39</td><td><em>(coverage pass)</em></td><td>CLI <code>main</code> wasn&#39;t exported, so help/unknown-command/<code>init</code>/<code>doctor</code> dispatch cases (lines 602-634) were subprocess-only (37.8% stmts)</td><td><code>main</code> exported; direct tests cover help variants, unknown-command exit 2 + stderr hint, <code>init</code> via <code>main</code>, and <code>doctor</code> incl. broken-config tolerance — entrypoint 37.8% → 46.3%</td></tr><tr><td>40</td><td><em>(coverage pass)</em></td><td>PHP parser edge branches uncovered: variable class target (<code>createMock($className)</code>), foreign-property assignment, dynamic member name, <code>new</code> operand</td><td>new <code>EdgeCasesTest.php</code> fixture + tests cover all four conservatively (variable target binds its members; foreign property never becomes a <code>this:</code> mock; dynamic member not bound; <code>new</code> classified re-evaluating) — parser-php 79.4% → 80.8% branches</td></tr><tr><td>41</td><td><em>(perf budget)</em></td><td>§2.7 <code>MCP tools/list &lt; 4 KB</code> budget was asserted nowhere</td><td>MCP integration test serializes the live <code>ListToolsResult</code> and asserts &lt; 4096 bytes</td></tr><tr><td>42</td><td><em>(dogfood, Chaos)</em></td><td><code>importOriginal</code> partial-mock factories (<code>vi.mock(&#39;mod&#39;, async (io) =&gt; { const a = await io(); return { ...a, key: vi.fn() }; })</code>) extracted <strong>zero</strong> factory keys — only expression-bodied factories were scanned</td><td>block-bodied factories are now scanned via <code>findReturnedObjectLiteral</code> (first object-literal return wins; <code>...actual</code> spread preserved as non-stub) — the stubbed exports (<code>readdirSync</code>, <code>runShellCommand</code>, …) become real members for DRIFT-005/TAUT; Chaos re-audit unchanged, no false positives</td></tr><tr><td>43</td><td><em>(coverage pass)</em></td><td><code>phpReturnExample</code>/<code>renderPhpType</code> union, intersection, and callable return branches in the PHP synth path were uncovered</td><td><code>DocblockTypes.php</code> gains <code>either()</code> (`int</td></tr><tr><td>44</td><td><em>(dogfood, git-diff on temp Chaos clone)</em></td><td>module-target mocks (<code>vi.mock</code> factories) have no <code>symbolId</code>, and <code>diffRelevant</code> required one — in precommit/<code>--git-diff</code> mode they were <strong>silently out of scope</strong>: a renamed export left the factory key dangling and <code>momus precommit</code> reported CLEAN (exit 0) while a plain audit fired DRIFT-005</td><td><code>diffRelevant</code> now resolves module-target mocks via their changed <code>modulePath</code>; DRIFT-006 gained a module-target branch (module file changed + mock file untouched → stale, message lists module basename + exports, budget-fitted). Planted rename on the temp clone fires DRIFT-005 errors + DRIFT-006 warnings with exit 1; healthy twin clears. Rule-level + CLI e2e regression tests</td></tr><tr><td>45</td><td><em>(dogfood, MCP git-diff on temp Knossos clone)</em></td><td>PHP class-target mocks in the MCP <code>verify_mock_drift</code> git-diff scope had no regression coverage</td><td>planted <code>client()</code> → <code>clientRenamed()</code> fired 8 DRIFT-001 + 11 DRIFT-006 via the MCP tool; healthy twin → 0. New PHP git-diff MCP integration test (<code>.momusrc</code> php:true fixture repo) pins the path</td></tr><tr><td>46</td><td><em>(Jest probe)</em></td><td><code>jest.doMock(&#39;mod&#39;, factory)</code> — Jest&#39;s one-off module mock with identical factory semantics — was invisible (only its inner <code>jest.fn</code> was extracted)</td><td>matched as its own <code>jest.doMock</code> pattern with <code>mockFactoryKey</code> members; <code>MockPattern</code> union extended; regression test pins factory-key extraction</td></tr><tr><td>47</td><td><em>(Jest probe, 2nd pass)</em></td><td><code>jest.genMockFromModule</code> (deprecated alias of <code>jest.createMockFromModule</code>) was invisible</td><td>now matched as an automock pattern; <code>jest.unmock</code>/<code>requireActual</code>/<code>isolateModules</code>/<code>replaceProperty</code> verified as correctly-non-mocks by probe</td></tr><tr><td>48</td><td><em>(perf budget)</em></td><td>§2.7 time/memory budgets were asserted nowhere; the workspace-time budget was documented-only</td><td><code>packages/core/test/perf.test.ts</code> generates a 100k-LOC PHP workspace and asserts 15s/500 MB ceilings (normative 2s/200 MB; probe measured 169ms/45 MB) + correct findings at scale; a lazy <code>require(&#39;@momus/parser-php&#39;)</code> in the test initially tanked coverage (91.6→85%) via a second module-graph copy — top-level import fixes it</td></tr><tr><td>49</td><td><em>(dogfood, Chaos <code>--max-issues 0</code>)</em></td><td>the markdown header printed the <strong>shown</strong> (post-truncation) counts while <code>CLEAN:</code> used the totals — so <code>momus audit . --max-issues 0</code> on a repo with findings printed <code>0 issues … CLEAN:false … more issues omitted</code>, a self-contradictory headline that masks findings for a human reader</td><td>header now prints the pre-truncation <strong>totals</strong> (<code>totalIssues</code>/<code>totalErrors</code>/<code>totalWarnings</code>/<code>totalInfos</code>), consistent with <code>CLEAN:</code> and the exit code; regression test pins <code>4 issues … CLEAN:false</code> for a fully-truncated run</td></tr><tr><td>50</td><td><em>(mutation testing, glob)</em></td><td><code>matchGlob</code> normalized backslashes in the <strong>pattern</strong> only, never the <strong>path</strong> — the old &quot;normalizes windows separators&quot; test passed by accident (backslashes are just non-slash chars, so <code>**</code> swallowed them whole), so <code>matchGlob(&#39;src/a.ts&#39;, &#39;src\\\\a.ts&#39;)</code> returned <code>false</code></td><td><code>matchGlob</code> now normalizes both sides; regression tests cover path + pattern normalization (found by a Stryker <code>StringLiteral</code> survivor on the <code>pattern.replace(/\\\\/g, &#39;/&#39;)</code> line)</td></tr></tbody></table><h2 id="_3-findings-about-root-chaos-mcp-typescript" tabindex="-1">3. Findings about <code>/root/Chaos-MCP</code> (TypeScript) <a class="header-anchor" href="#_3-findings-about-root-chaos-mcp-typescript" aria-label="Permalink to &quot;3. Findings about `/root/Chaos-MCP` (TypeScript)&quot;">​</a></h2><p>Verified against source after fixes; working tree at commit <code>a65faae</code>.</p><ul><li><strong>DRIFT-006</strong> (git-diff <code>HEAD~10</code>): 6 stale-mock warnings — <code>estimate-handler.test.ts</code> and <code>handler-container.test.ts</code> mock <code>estimateAudit</code>/<code>estimateNeedsSandbox</code>/<code>createExecutionSession</code> from <code>core/estimate.ts</code>, <code>estimate-handler.ts</code>, <code>utils/execution.ts</code>, which changed in that range while the test files did not. <strong>True positives.</strong></li><li><strong>Remaining warnings (0 errors):</strong> MOCK-001 (4, mock-heavy unit tests — heuristic, working as intended: <code>handler-container</code>, <code>index</code>, <code>python-interpreter-memo</code>, <code>triage-discover-targets</code>).</li><li><strong>Resolved false positives:</strong> TAUT-005 (scope-aware hand-off, <strong>107 → 0</strong>), TAUT-006 (spied-object hand-off, <strong>5 → 0</strong>), the TAUT-001 determinism test (<code>expect(f(x)).toBe(f(x))</code> — a re-evaluating call, now correctly not flagged), and TAUT-004 (<strong>21 → 0</strong> — <code>productionCalls</code> now sees SUT instances assigned in <code>beforeEach</code>, traces local helper functions that wrap the SUT, collects <code>it.each</code>/<code>test.each</code> tests, and counts a dynamic <code>import()</code> as executing production code).</li></ul><h2 id="_4-findings-about-root-knossos-mcp-php" tabindex="-1">4. Findings about <code>/root/Knossos-MCP</code> (PHP) <a class="header-anchor" href="#_4-findings-about-root-knossos-mcp-php" aria-label="Permalink to &quot;4. Findings about `/root/Knossos-MCP` (PHP)&quot;">​</a></h2><p>Verified against source after fixes; working tree at commit <code>3ff6b0c</code> (now with a <code>vendor/</code> dir).</p><ul><li><strong>TAUT-001 / TAUT-003</strong> (<code>tests/phpunit/Cli/CliHelpersTest.php:322,530,568</code>): <code>assertSame(true, true)</code> with the author&#39;s own <code>// sentinel</code> comments — <strong>true positives</strong> (no-op smoke assertions).</li><li><strong>TAUT-005</strong> (0 warnings, was 8 → 5 → 0): <code>createStub(PDO::class)</code> / <code>PDOStatement</code> configured then passed into the SUT (<code>new ProjectWriterLease($pdo, …)</code>, <code>new ProjectWriterLock($pdo)</code>) or returned from a <code>willReturnCallback</code> closure (<code>return $stmt;</code>). After wiring constructor/call/return hand-off reachability, all were correctly marked reachable.</li><li><strong>Drift:</strong> CLEAN. Mocks target <code>LanguageWorkerPool</code> (own class, resolves via PSR-4 to <code>src/Scan/LanguageWorkerPool.php</code>) and <code>PDO</code>/<code>PDOStatement</code> (PHP built-ins, correctly skipped).</li><li><strong><code>willThrowException</code> now recognized</strong> as a config call (like <code>willReturnCallback</code>), which removed 3 of the TAUT-005 warnings (the throw-configured <code>$pool</code>/<code>$pdo</code> mocks are now marked reachable instead of zero-reach). The thrown exception expression is now also captured in the IR as mock-level config (row 23).</li><li><strong>Remaining findings are the 6 genuine <code>assertSame(true, true)</code> sentinels</strong> — true positives (the author&#39;s own <code>// sentinel</code> comments).</li><li><strong>DRIFT-001 / DRIFT-003 drill-down: 0 issues</strong> on the full corpus — the drift rules produce no false positives (and no true positives: Knossos genuinely has no planted drift).</li><li><strong>MCP round-trip verified</strong> against Knossos with all 5 tools, twice: once over the in-memory transport and once over a <strong>real stdio subprocess</strong> (temp <code>.momusrc</code> with PHP enabled + cache disabled, removed after). Both give: <code>listTools</code> → 5, <code>list_rules</code> → 14, <code>verify_mock_drift</code> → 0, <code>detect_tautological_assertions</code> → 6 sentinels, <code>audit_test_fidelity</code> on <code>CliHelpersTest.php</code> → 6, <code>synthesize_mock_contract</code> on <code>LanguageWorkerPool.php</code> → correct <code>phpunit</code> template.</li><li><strong>Sentinel decision:</strong> the 6 <code>assertSame(true, true)</code> hits are correct true positives, not a Momus bug. The author uses them as no-op smoke/skip markers (<code>// sentinel</code> — <code>assertTrue</code> is absent from <code>Support/Assertions.php</code>). Recommendation for Knossos (not a Momus change): add <code>assertTrue</code> to the assertion shim, or use PHPUnit&#39;s <code>expectNotToPerformAssertions()</code> / a proper <code>markTestSkipped</code> for the pcntl-guard case — the current lines give false confidence.</li></ul><h2 id="_4b-self-dogfooding-momus-on-momus" tabindex="-1">4b. Self-dogfooding (Momus on Momus) <a class="header-anchor" href="#_4b-self-dogfooding-momus-on-momus" aria-label="Permalink to &quot;4b. Self-dogfooding (Momus on Momus)&quot;">​</a></h2><ul><li><strong>Full audit incl. DRIFT-000: 0 issues</strong> on 59 files (all 23 test files + production source). The tool&#39;s own test suite genuinely exercises the drift/tautology rules (36 <code>vi.fn</code>, 20 <code>vi.spyOn</code>, 6 <code>vi.mock</code>) and stays clean.</li><li><strong>git-diff drift (<code>--base HEAD~15</code>): CLEAN</strong> — no DRIFT-006 stale-mock.</li><li><strong><code>momus contract</code> on its own classes</strong> surfaced two real synthesis bugs (fixed, rows 16–17): string-literal union aliases emitted <code>{ length: 0 }</code>, and inline type literals didn&#39;t recurse through the checker. Post-fix, <code>momus contract packages/core/src/audit.ts</code> produces a fully correct nested literal for <code>AuditResult</code> (<code>summary: { … truncated: false }</code>, <code>issues: []</code>, <code>indexStats: { modules: 0, symbols: 0, mocks: 0 }</code>).</li><li><strong>Second dogfooding pass</strong> surfaced three more synthesis bugs (fixed, rows 18–20): generic methods and generic classes emitted out-of-scope type parameters (now concretized to <code>unknown</code>, with <code>Partial&lt;Box&lt;unknown&gt;&gt;</code> for generic classes), and interface targets returned <code>no class found</code> (now supported — data properties become plain values, methods become <code>vi.fn</code> stubs). <code>momus contract packages/core/src/ir.ts --symbol ModuleIR</code> now yields a correct 13-property <code>ModuleIR</code> mock.</li></ul><h2 id="_5-open-candidate-improvements" tabindex="-1">5. Open / candidate improvements <a class="header-anchor" href="#_5-open-candidate-improvements" aria-label="Permalink to &quot;5. Open / candidate improvements&quot;">​</a></h2><ol><li>✅ PHP <code>willThrowException</code>&#39;s exception value is now recorded in the IR as mock-level config (<code>configuredValues</code>, api <code>willThrowException</code>) — implemented. It is deliberately <strong>not</strong> a return value, so DRIFT-003 never compares an exception against the production return type. (Left: surfacing the exception value in the <code>synthesize_mock_contract</code> PHP templates.)</li><li>✅ TS synthesis now resolves <strong>named</strong> interface/class returns through the type checker (<code>tsReturnExampleChecked</code>), so <code>User</code> / <code>Promise&lt;User&gt;</code> emit data-shape literals (<code>mockResolvedValue({ id: 0, … })</code>) instead of <code>undefined</code>. <code>Record&lt;K, V&gt;</code> / index-signature types (<code>NodeJS.ProcessEnv</code>) emit <code>{}</code>. Method-bearing shapes now emit <code>vi.fn()</code> stubs too: inline type literals with method signatures (<code>{ run(): void }</code> → <code>{ run: vi.fn() }</code>), function-typed properties (<code>cb: (x: number) =&gt; void</code> → <code>cb: vi.fn()</code>), and named interfaces with methods (data properties as values, methods as <code>vi.fn</code>). Remaining nuance: optional members are included with their example value (<code>zip?: number</code> → <code>zip: 0</code>).</li><li>✅ PHP synthesis surfaces <code>@throws</code> docblocks: the parser now extracts exception class names into <code>SignatureIR.throws</code> (IR schema v3), and <code>synthesize_mock_contract</code> emits a commented <code>willThrowException</code> (phpunit) / <code>andThrow</code> (pest) alternative per <code>@throws</code>-documented method. The doc-type tokenizer also handles generics with spaces (<code>array&lt;int, Invoice&gt;</code>) — see row 26.</li><li>MOCK-001 (over-mocking) remains a heuristic warning — it intentionally flags mock-heavy unit tests; tuning its threshold or production-assertion counting is a judgment call, not a bug.</li><li>TAUT-004&#39;s last survivor is a dynamic-<code>import()</code> + indirect signal-handler invocation (<code>(sigCall[1])()</code> from a spy&#39;s <code>.mock.calls</code>) — statically untraceable without full interprocedural analysis.</li><li>✅ The 5s vitest default timeout flaked under parallel coverage on three tests (git-diff MCP, syntax-only, in-memory audit); a global <code>testTimeout: 15s</code> now covers instrumentation headroom without masking real hangs. Coverage gate holds at 80/75/90.</li><li>PHP parser coverage raised 88.4→96.6% stmts / 100% funcs via new fixtures: <code>createPartialMock</code> member lists, <code>createConfiguredMock</code> array values, PHPDoc type-syntax variants, and a deliberately broken file exercising the SYS-001 parse-error diagnostic.</li><li>✅ TS DRIFT-003 now fires for spyOn-bound configs (rows 27–29): a new <code>computeReturnAssignability</code> pass runs for <code>vi.spyOn</code>/<code>jest.spyOn</code> mocks (previously only <code>vi.mocked</code> instances), the value node resolves to the config <strong>argument</strong> (not the callee), owner resolution is position-aware, and casts are unwrapped. Planted fixture (<code>mockReturnValue(&#39;nope&#39;)</code> on <code>totalCents(): number</code>) → DRIFT-003 warning; healthy twin quiet.</li><li>✅ Member calls on a spied-on object now mark the matching spy reached (<code>svc.totalCents()</code> invokes the <code>vi.spyOn(svc, &#39;totalCents&#39;)</code> spy) — removes TAUT-005 false positives on the standard spy+call pattern while preserving TAUT-006 (member names must match, so <code>service.totalFor()</code> never satisfies a spy on <code>totalForX</code>).</li><li>✅ <code>momus --root DIR</code> is honored by every command (row 30): audit/drift/hook/contract/rules/ init/doctor/serve run against DIR from any cwd (mirrors the MCP server&#39;s <code>MOMUS_ROOT</code>). Regression test runs the bin from an empty cwd with <code>--root</code> pointing at a target repo.</li><li>✅ TS DRIFT-003 assignability now covers the full spy-config surface: <code>mockReturnValueOnce</code> / <code>mockResolvedValueOnce</code> flow through the same pass (fixture: planted once-mismatch fires), <code>mockImplementation</code>/<code>mockImplementationOnce</code> callback <strong>returns</strong> are checked against the production return type (<code>spy.mockImplementation(() =&gt; &#39;nope&#39;)</code> on <code>totalCents(): number</code> fires), and <code>mockRejectedValue</code> is correctly exempted (row 31 — a rejection reason, not a resolved value). Dogfooded on Momus itself (20+ spyOn uses): 0 issues; Chaos re-audit unchanged (0 errors / 4 MOCK-001).</li><li>✅ DRIFT-002 parameter assignability tree covered (rows 32): union-union no longer false- flags; named params compare names + type args; array/tuple element-wise; literal-vs-named handled in both directions. New direct rule tests exercise every <code>typeAssignable</code> branch.</li><li>✅ Coverage pass: <code>markdown.ts</code> 100% branches (pluralization edges), <code>symbolIndex.ts</code> 100% stmts/branches (new direct unit tests: inheritance, diamond dedupe, missing extends, same-module <code>resolveByName</code>, exports), and direct PHP DRIFT-003 rule tests for the <code>phpReturnAssignable</code> tree (mixed/void/null/union/class-resolution branches).</li><li>✅ CLI <code>main()</code> dispatch extracted into exported per-command functions (<code>runAudit</code>/<code>runDrift</code>/ <code>runPrecommit</code>/<code>runHook</code>/<code>runContract</code>/<code>runRules</code>/<code>runServe</code>/<code>runInit</code>/<code>runDoctor</code>/ <code>runAnnotate</code>/<code>runAnnotatePr</code>) with a thin <code>main</code> mapper — commands are now unit-testable without spawning a subprocess (2 direct tests added); CLI entrypoint coverage 19.4% → 37.8%. Note: the ts.Program cache is memoized per process, so calling a run* twice on the same path in one process can serve a stale program — the real CLI invokes one command per process.</li><li>✅ SYS-004 (perf-budget, §2.7) is now real, not just a declared code: a per-file parse over the budget (<code>AuditOptions.parseBudgetMs</code>, default 2s — well above the 50ms normative budget to keep CI timing-flake-free) emits an info diagnostic and the audit still completes. Unit tests drive a busy-wait parser against a 1ms budget (fires) and a 5s budget (quiet). Row 35.</li><li>✅ CI now runs <code>npm run lint</code> + <code>npm run format:check</code> in the test job — the style gates were script-only before.</li><li>✅ CLI entrypoint coverage 37.8% → 46.3%: <code>main</code> is now exported, and direct tests (no subprocess) cover help/<code>--help</code>/<code>-h</code>, unknown-command exit 2, <code>init</code> dispatch through <code>main</code>, and <code>doctor</code> incl. a broken-<code>.momusrc</code> tolerance path (rows 39–40).</li><li>✅ PHP parser branch coverage 79.4% → 80.8% + a <strong>real bug fixed</strong>: <code>phpValue</code> classified <code>new X()</code> as a literal (<code>constant: true</code>), so <code>assertNotSame(new Engine(), $engine)</code> could be read as a self-comparison; a <code>new</code> expression re-evaluates (fresh object), so it now falls through to <code>exprKind</code> → <code>&#39;new&#39;</code> (row 38). New <code>EdgeCasesTest.php</code> fixture also covers variable class targets (<code>createMock($className)</code>), non-<code>$this</code> property assignments (correctly not bound as <code>this:</code> mocks), and dynamic member names (conservatively not bound). Knossos re-audit unchanged.</li><li>✅ §2.7 perf budget <code>MCP tools/list serialized size &lt; 4 KB</code> is now asserted in the MCP integration test (the SDK&#39;s <code>ListToolsResult</code> payload is serialized and measured); the workspace-time budget stays documented-only because a wall-clock assert on a 100k-LOC workspace would flake under CI/coverage instrumentation.</li><li>✅ Dogfood gap found on Chaos-MCP: <strong><code>importOriginal</code> partial-mock factories lost their override keys</strong>. <code>vi.mock(&#39;mod&#39;, async (io) =&gt; { const a = await io(); return { ...a, key: vi.fn() }; })</code> produced a mock with <strong>zero</strong> stubbed members (only expression-bodied factories were scanned), so the stubbed exports were invisible to DRIFT-005/TAUT rules. <code>findReturnedObjectLiteral</code> now scans block bodies; the <code>...actual</code> spread is preserved as a non-stub. Regression tests cover both the block-bodied <code>importOriginal</code> form and the non-object fallback (row 42). Chaos re-audit unchanged (4 MOCK-001 / 0 errors) — no false positives from the richer extraction.</li><li>✅ PHP synth render branches covered: <code>phpReturnExample</code> union (non-null member drives the example: <code>int|string</code> → <code>andReturn(0)</code>), intersection, and callable returns stay conservative (<code>null</code>), via new <code>either</code>/<code>both</code>/<code>factory</code> methods on <code>DocblockTypes.php</code> (row 43). Server stmts 91.5 → 92.1%.</li><li>✅ <strong>Real precommit bug found by dogfooding the git-diff flow on a temp clone of Chaos-MCP</strong>: module-target mocks (<code>vi.mock</code>/<code>jest.mock</code> factories) have <strong>no <code>symbolId</code></strong>, and <code>diffRelevant</code> required one — so in <code>precommit</code>/<code>--git-diff</code> mode they were silently out of scope. A renamed production export left the <code>vi.mock</code> factory key dangling and precommit reported <strong>CLEAN</strong> (exit 0) while a plain audit correctly fired DRIFT-005. <code>diffRelevant</code> now resolves module-target mocks through their changed <code>modulePath</code>, and DRIFT-006 (stale-mock) gained a module-target branch (stale when the module file changed + mock file untouched; message lists the module basename + export names, budget-fitted). Planted rename on the temp clone now fires DRIFT-005 errors + DRIFT-006 warnings across every affected test file with exit 1; the healthy twin (factory key updated alongside) clears. Regression tests at rule level (diff.test.ts) and CLI end-to-end (row 44).</li><li>✅ Dogfooded the <strong>MCP <code>verify_mock_drift</code> git-diff scope on a temp clone of Knossos-MCP (PHP)</strong>: planted <code>client()</code> → <code>clientRenamed()</code> in <code>LanguageWorkerPool.php</code> with <code>LanguageScanRunnerTest</code>&#39;s <code>createStub</code><ul><li><code>-&gt;method(&#39;client&#39;)</code> untouched → the tool surfaced <strong>8 DRIFT-001 errors + 11 DRIFT-006 warnings</strong>; the healthy twin (stub updated to <code>clientRenamed</code>) cleared to 0. PHP class-target mocks participate in diff scope exactly like TS. Added a PHP git-diff MCP integration test (fixture repo with <code>.momusrc</code> php:true) so the path stays regressed (row 45).</li></ul></li><li>✅ Jest probe: <code>jest.doMock(&#39;mod&#39;, () =&gt; ({...}))</code> (one-off module mock, same factory semantics as <code>jest.mock</code>) was invisible — only its inner <code>jest.fn</code> was caught. Now matched as its own <code>jest.doMock</code> pattern with <code>mockFactoryKey</code> members; <code>MockPattern</code> union extended. Regression test pins the factory-key extraction (row 46). Second pass: <code>jest.genMockFromModule</code> (deprecated alias of <code>jest.createMockFromModule</code>) was also invisible — now matched as an automock. <code>jest.unmock</code>/ <code>jest.requireActual</code>/<code>jest.isolateModules</code>/<code>jest.replaceProperty</code> are correctly <strong>not</strong> mocks (verified by probe, no change).</li><li>✅ <strong>§2.7 perf budgets now asserted</strong> (row 47): <code>packages/core/test/perf.test.ts</code> generates a deterministic 100k-LOC PHP workspace (500 classes × 100 methods) in a temp dir, audits it, and asserts the time/memory budgets with CI-tolerant ceilings (15s / 500 MB vs normative 2s / 200 MB — the real signal is no order-of-magnitude regression, and the probe measured <strong>169ms / 45 MB</strong>). It also asserts the planted 500 TAUT-002 echoes still fire at scale (<code>totalIssues</code>, since <code>maxIssues: 0</code> truncates <code>issues</code>). Gotcha found while writing it: a <strong>lazy <code>require(&#39;@momus/parser-php&#39;)</code> inside the test function</strong> loaded a second copy of the module graph (parser-php&#39;s own <code>@momus/core</code> dependency) and confused v8 coverage — dropping <code>All files</code> from 91.6% → 85%; top-level <code>import { PhpParser }</code> fixed it (and <code>config.ts</code>/<code>audit.ts</code> etc. returned to their real numbers).</li><li>✅ Release tooling migrated from changesets to <strong>release-please</strong> modeled on Knossos-MCP (single lockstep version from <strong>0.0.1</strong>): <code>release-please-config.json</code> (json extra-files bump all five workspace <code>package.json</code>s) + <code>.release-please-manifest.json</code>; <code>pr-title.yml</code> conventional-commit gate; <code>.github/workflows/release-please.yml</code> (version-PR → <code>v*</code> tag + GitHub Release → gate + <code>npm run publish</code> on <code>release_created</code>); <code>scripts/publish.mjs</code> (dependency-ordered <code>npm publish -w</code>). Internal <code>@momus/*</code> deps re-pinned <code>~0.0.1</code> so they track in lockstep. Two verification layers: <code>scripts/verify-release-config.mjs</code> (deterministic, no-network consistency check wired into <code>ci.yml</code> + <code>test/release-config.test.ts</code>) and <code>scripts/simulate-release.mjs</code> (round-trips the release flow in an isolated worktree: bump 0.0.1 → 0.0.2 exactly as release-please would → <code>npm ci</code> → <code>npm publish</code> dry-run → asserts all five packages pack at 0.0.2 and <code>~</code> ranges admit the bump). MCP <code>serverInfo.version</code> is now read from <code>@momus/mcp-server</code>&#39;s package.json at runtime (was hardcoded <code>0.1.0</code>); pinned by an integration test. First live runs against the real GitHub API surfaced three more fixes: <code>json</code> extra-files need a <code>jsonpath</code> property; <code>bump-patch-for-minor-pre-major: true</code> keeps pre-1.0 releases in 0.0.x so the <code>~0.0.1</code> internal dep ranges resolve on release branches; and <strong>npm publishing was removed from CI entirely</strong> (manual-only by decision — tags/releases cut automatically, npm never touched until publishing is sanctioned). v0.0.1 bootstrapped + v0.0.2 cut automatically (PR → merge → tag + release with changelog); main branch protected (PRs only, required checks, strict up-to-date, enforced for admins).</li><li>✅ Dogfood probe round (no code gaps found): <code>vi.hoisted(() =&gt; vi.fn())</code> and <code>vi.hoisted(() =&gt; ({ key: vi.fn() }))</code> — the pervasive real-world pattern for sharing mock fns with <code>vi.mock</code> factories — resolve correctly on Chaos-MCP: the hoisted <code>vi.fn</code> is a standalone mock, the factory keys (<code>listChangedFiles</code>, <code>Server</code>, …) extract as <code>mockFactoryKey</code> stubs, and MOCK-001 counts stay accurate (no double-counting, no false TAUT/DRIFT). Class-valued factory keys (<code>Server: class { … }</code>) also extract. Chaos re-audit unchanged (0 errors / 4 MOCK-001); Knossos unchanged (6 sentinel errors, all deliberate <code>assertSame(true, true)</code> markers).</li></ol>',17)])])}const h=o(s,[["render",r]]);export{p as __pageData,h as default};
